<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { createPlotArchive, getFarmArchives, getPlotArchives, updatePlotArchive } from '@/api/adminPhase2'
const rows=ref([]);const farms=ref([]);const dialog=ref(false);const editing=ref('');const empty={farmId:'',plotCode:'',plotName:'',areaMu:null,location:'',irrigationMethod:'滴灌',farmerUserId:null,status:'ACTIVE'};const form=reactive({...empty})
async function load(){[rows.value,farms.value]=await Promise.all([getPlotArchives(),getFarmArchives()])}
function open(row){editing.value=row?.id||'';Object.assign(form,row||empty);dialog.value=true}
async function save(){if(editing.value)await updatePlotArchive(editing.value,form);else await createPlotArchive(form);dialog.value=false;await load();ElMessage.success('地块档案已保存')}
onMounted(load)
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">地块档案</h1><p class="page-subtitle">维护全平台唯一地块编号、面积、位置、灌溉方式与状态。</p></div><el-button type="primary" @click="open()">新增地块</el-button></div><section class="content-panel"><el-table :data="rows"><el-table-column prop="plotCode" label="地块编号"/><el-table-column prop="plotName" label="名称"/><el-table-column prop="farmId" label="所属橙园"/><el-table-column prop="areaMu" label="面积（亩）"/><el-table-column prop="irrigationMethod" label="灌溉方式"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" :title="editing?'编辑地块':'新增地块'" width="600px"><el-form label-width="100px"><el-form-item label="所属橙园"><el-select v-model="form.farmId"><el-option v-for="item in farms" :key="item.id" :label="item.farmName" :value="item.id"/></el-select></el-form-item><el-form-item label="编号"><el-input v-model="form.plotCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.plotName"/></el-form-item><el-form-item label="面积（亩）"><el-input-number v-model="form.areaMu" :min="0"/></el-form-item><el-form-item label="位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="灌溉方式"><el-input v-model="form.irrigationMethod"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" active-value="ACTIVE" inactive-value="INACTIVE" active-text="启用" inactive-text="停用"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
